-- Reusable applicant-portal Storybook components; operational admin components are excluded.
create table public.components (
  id text primary key,
  key text not null unique,
  position integer not null default 0,
  definition jsonb not null check (jsonb_typeof(definition) = 'object'),
  display_id bigint not null unique check (display_id > 0),
  provided_by text references public.provenance_tags(key),
  source_reference text
);
alter table public.components enable row level security;
grant select on public.components to authenticated;
grant all on public.components to service_role;
-- Match the read-only Library access boundary; writes use reviewed publication.
create policy components_read on public.components for select to authenticated
  using (public.portal_require_admin() = auth.uid());


